(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanillajs';
  var newTodoInput = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var toggleAll = document.querySelector('#toggle-all');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var todoCount = document.querySelector('.todo-count');
  var mainSection = document.querySelector('.main');
  var footerSection = document.querySelector('.footer');

  // --- Storage ---

  function loadTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  // --- Route ---

  function getRoute() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function getFilteredTodos(todos) {
    var route = getRoute();
    if (route === 'active') return todos.filter(function (t) { return !t.completed; });
    if (route === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  // --- Render ---

  /** @planks("I navigate to {string}") @planks("the page is reloaded") */
  function render() {
    var todos = loadTodos();
    var filtered = getFilteredTodos(todos);

    // Build map of existing DOM nodes by data-id
    var existingNodes = {};
    var existingLis = todoList.querySelectorAll('li');
    for (var i = 0; i < existingLis.length; i++) {
      var existingLi = existingLis[i];
      existingNodes[existingLi.getAttribute('data-id')] = existingLi;
    }

    // Clean editing state from all items before re-rendering
    var allLis = todoList.querySelectorAll('li');
    for (var j = 0; j < allLis.length; j++) {
      allLis[j].classList.remove('editing');
    }

    // Track which data-ids are needed
    var neededIds = {};

    // Render each todo, reusing existing DOM nodes
    filtered.forEach(function (todo) {
      var id = String(todo.id);
      neededIds[id] = true;
      var li = existingNodes[id];

      if (li) {
        // Update existing node in place
        if (todo.completed) {
          li.classList.add('completed');
        } else {
          li.classList.remove('completed');
        }
        var toggle = li.querySelector('.toggle');
        if (toggle) toggle.checked = todo.completed;
        var label = li.querySelector('.view label');
        if (label) label.textContent = todo.title;
        var editInput = li.querySelector('.edit');
        if (editInput) editInput.value = todo.title;
      } else {
        // Create new node
        li = document.createElement('li');
        li.setAttribute('data-id', id);
        if (todo.completed) li.classList.add('completed');
        li.innerHTML =
          '<div class="view">' +
            '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
            '<label>' + escapeHtml(todo.title) + '</label>' +
            '<button class="destroy"></button>' +
          '</div>' +
          '<input class="edit" value="' + escapeHtml(todo.title) + '">';
        todoList.appendChild(li);
      }
    });

    // Remove nodes for todos not in filtered list
    for (var existingId in existingNodes) {
      if (!neededIds[existingId]) {
        todoList.removeChild(existingNodes[existingId]);
      }
    }

    // Counter
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var pluralized = activeCount === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + pluralized + ' left';

    // Toggle all state
    var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });
    toggleAll.checked = allCompleted;

    // Section visibility
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footerSection.style.display = 'none';
    } else {
      mainSection.style.display = '';
      footerSection.style.display = '';
    }

    // Clear completed visibility
    var completedCount = todos.filter(function (t) { return t.completed; }).length;
    clearCompletedBtn.style.display = completedCount > 0 ? '' : 'none';

    // Filter links
    var route = getRoute();
    var links = document.querySelectorAll('.filters a');
    for (var i = 0; i < links.length; i++) {
      var link = links[i];
      var linkRoute = link.getAttribute('href');
      if (
        (route === 'all' && linkRoute === '#/') ||
        (route === 'active' && linkRoute === '#/active') ||
        (route === 'completed' && linkRoute === '#/completed')
      ) {
        link.classList.add('selected');
      } else {
        link.classList.remove('selected');
      }
    }
  }

  function escapeHtml(text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
  }

  // --- Todo operations ---

  var nextId = 1;

  /** @planks("I have added a todo {string}") @planks("I press Enter in the new-todo input") @planks("I type {string} in the new-todo input") */
  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;
    var todos = loadTodos();
    todos.push({ id: nextId++, title: trimmed, completed: false });
    saveTodos(todos);
    render();
  }

  /** @planks("I click the checkbox of the todo {string}") @planks("I complete the todo {string}") @planks("I uncomplete the todo {string}") */
  function toggleTodo(id) {
    var todos = loadTodos();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    saveTodos(todos);
    render();
  }

  /** @planks("I click the toggle-all checkbox") */
  function toggleAllTodos() {
    var todos = loadTodos();
    var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });
    todos.forEach(function (t) { t.completed = !allCompleted; });
    saveTodos(todos);
    render();
  }

  /** @planks("I destroy the todo {string}") */
  function destroyTodo(id) {
    var todos = loadTodos().filter(function (t) { return t.id !== id; });
    saveTodos(todos);
    render();
  }

  /** @planks("I press Enter in the edit input of {string}") @planks("I blur the edit input of {string}") @planks("I press Escape in the edit input of {string}") */
  function editTodo(id, newTitle) {
    var trimmed = newTitle.trim();
    var todos = loadTodos();
    if (trimmed === '') {
      todos = todos.filter(function (t) { return t.id !== id; });
    } else {
      for (var i = 0; i < todos.length; i++) {
        if (todos[i].id === id) {
          todos[i].title = trimmed;
          break;
        }
      }
    }
    saveTodos(todos);
    render();
  }

  /** @planks("I click the clear-completed button") */
  function clearCompleted() {
    var todos = loadTodos().filter(function (t) { return !t.completed; });
    saveTodos(todos);
    render();
  }

  function findTodoId(li) {
    return parseInt(li.getAttribute('data-id'), 10);
  }

  // --- Event handlers ---

  // New todo input
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.keyCode === 13) {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  });

  // Delegated events on todo list
  todoList.addEventListener('click', function (e) {
    var target = e.target;
    var li = target.closest('li');
    if (!li) return;
    var id = findTodoId(li);

    if (target.classList.contains('toggle')) {
      toggleTodo(id);
    } else if (target.classList.contains('destroy')) {
      destroyTodo(id);
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    var target = e.target;
    if (target.tagName !== 'LABEL') return;
    var li = target.closest('li');
    if (!li) return;
    li.classList.add('editing');
    var editInput = li.querySelector('.edit');
    editInput.focus();
  });

  todoList.addEventListener('keydown', function (e) {
    var target = e.target;
    if (!target.classList.contains('edit')) return;
    var li = target.closest('li');
    var id = findTodoId(li);

    if (e.key === 'Enter' || e.keyCode === 13) {
      editTodo(id, target.value);
    } else if (e.key === 'Escape' || e.keyCode === 27) {
      target.value = li.querySelector('.view label').textContent;
      li.classList.remove('editing');
    }
  });

  todoList.addEventListener('blur', function (e) {
    var target = e.target;
    if (!target.classList.contains('edit')) return;
    var li = target.closest('li');
    if (!li) return;
    if (!li.classList.contains('editing')) return;
    var id = findTodoId(li);
    editTodo(id, target.value);
  }, true);

  // Toggle all
  toggleAll.addEventListener('click', function () {
    toggleAllTodos();
  });

  // Clear completed
  clearCompletedBtn.addEventListener('click', function () {
    clearCompleted();
  });

  // Route change
  window.addEventListener('hashchange', function () {
    render();
  });

  // --- Init ---
  render();
  newTodoInput.focus();
})();

const { Given, When, Then } = require('@cucumber/cucumber');
const fs = require('node:fs');
const path = require('node:path');
const ROOT = path.resolve(__dirname, '..', '..');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function el(root, selector) {
  return root.querySelector(selector);
}

function todos(root) {
  return Array.from(root.querySelectorAll('.todo-list li'));
}

function todoByTitle(root, title) {
  return todos(root).find(
    (li) => el(li, '.view label')?.textContent?.trim() === title,
  );
}

function pressEnter(input) {
  input.dispatchEvent(
    new input.ownerDocument.defaultView.KeyboardEvent('keydown', {
      key: 'Enter',
      code: 'Enter',
      keyCode: 13,
      which: 13,
      bubbles: true,
    }),
  );
}

function pressEscape(input) {
  input.dispatchEvent(
    new input.ownerDocument.defaultView.KeyboardEvent('keydown', {
      key: 'Escape',
      code: 'Escape',
      keyCode: 27,
      which: 27,
      bubbles: true,
    }),
  );
}

function typeText(input, text) {
  input.value = text;
  input.dispatchEvent(new input.ownerDocument.defaultView.Event('input', { bubbles: true }));
}

// ---------------------------------------------------------------------------
// Given
// ---------------------------------------------------------------------------

Given('the app is loaded', function () {
  // App is loaded by the Before hook in world.js; this step is a no-op.
});

function addTodoToWorld(world, title) {
  const input = el(world.document, '.new-todo');
  typeText(input, title);
  pressEnter(input);
}

Given('I have added a todo {string}', function (title) {
  addTodoToWorld(this, title);
});

Given('I have added todos {string} and {string}', function (t1, t2) {
  addTodoToWorld(this, t1);
  addTodoToWorld(this, t2);
});

Given('I have added todos {string} and {string} and {string}', function (t1, t2, t3) {
  addTodoToWorld(this, t1);
  addTodoToWorld(this, t2);
  addTodoToWorld(this, t3);
});

Given('all todos are completed', function () {
  const doc = this.document;
  const toggleAll = el(doc, '#toggle-all');
  if (!toggleAll.checked) {
    toggleAll.click();
  }
});

Given('the todo {string} is completed', function (title) {
  const li = todoByTitle(this.document, title);
  const checkbox = el(li, '.toggle');
  if (!checkbox.checked) checkbox.click();
});

Given('the todo {string} is in editing mode', function (title) {
  const li = todoByTitle(this.document, title);
  const label = el(li, '.view label');
  label.dispatchEvent(new this.document.defaultView.Event('dblclick', { bubbles: true }));
});

// 'the todo {string} is completed' and 'the todo {string} is in editing mode' are
// used as both Given (setup) and Then (assertion). One definition handles both:
// idempotent for Given, assertive for Then.

// ---------------------------------------------------------------------------
// When
// ---------------------------------------------------------------------------

When('I press Enter in the new-todo input', function () {
  const input = el(this.document, '.new-todo');
  pressEnter(input);
});

When('I type {string} in the new-todo input', function (text) {
  const input = el(this.document, '.new-todo');
  typeText(input, text);
});

When('I click the toggle-all checkbox', function () {
  el(this.document, '#toggle-all').click();
});

When('I click the checkbox of the todo {string}', function (title) {
  const li = todoByTitle(this.document, title);
  el(li, '.toggle').click();
});

When('I double-click the label of the todo {string}', function (title) {
  const li = todoByTitle(this.document, title);
  const label = el(li, '.view label');
  label.dispatchEvent(
    new this.document.defaultView.Event('dblclick', { bubbles: true }),
  );
});

When('I click the clear-completed button', function () {
  el(this.document, '.clear-completed').click();
});

When('I complete the todo {string}', function (title) {
  const li = todoByTitle(this.document, title);
  const checkbox = el(li, '.toggle');
  if (!checkbox.checked) {
    checkbox.click();
  }
});

When('I uncomplete the todo {string}', function (title) {
  const li = todoByTitle(this.document, title);
  const checkbox = el(li, '.toggle');
  if (checkbox.checked) {
    checkbox.click();
  }
});

When('I destroy the todo {string}', function (title) {
  const li = todoByTitle(this.document, title);
  el(li, '.destroy').click();
});

When('I clear the edit input of {string}', function (title) {
  const li = todoByTitle(this.document, title);
  const input = el(li, '.edit');
  input.value = '';
  input.dispatchEvent(new this.document.defaultView.Event('input', { bubbles: true }));
});

When('I type {string} in the edit input of {string}', function (text, title) {
  const li = todoByTitle(this.document, title);
  const input = el(li, '.edit');
  typeText(input, text);
});

When('I press Enter in the edit input of {string}', function (title) {
  const li = todoByTitle(this.document, title);
  const input = el(li, '.edit');
  pressEnter(input);
});

When('I press Escape in the edit input of {string}', function (title) {
  const li = todoByTitle(this.document, title);
  const input = el(li, '.edit');
  pressEscape(input);
});

When('I blur the edit input of {string}', function (title) {
  const li = todoByTitle(this.document, title);
  const input = el(li, '.edit');
  input.dispatchEvent(new this.document.defaultView.Event('blur', { bubbles: true }));
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('the page is reloaded', function () {
  this.loadApp();
});

// ---------------------------------------------------------------------------
// Then
// ---------------------------------------------------------------------------

Then('the todo list is empty', function () {
  const items = todos(this.document);
  if (items.length !== 0) {
    throw new Error(`Expected 0 todos, got ${items.length}`);
  }
});

Then('the todo list contains {int} item', function (count) {
  const items = todos(this.document);
  if (items.length !== count) {
    throw new Error(`Expected ${count} todos, got ${items.length}`);
  }
});

Then('the todo list contains {int} items', function (count) {
  const items = todos(this.document);
  if (items.length !== count) {
    throw new Error(`Expected ${count} todos, got ${items.length}`);
  }
});

Then('the first todo has title {string}', function (title) {
  const items = todos(this.document);
  if (items.length === 0) throw new Error('No todos in list');
  const actual = el(items[0], '.view label')?.textContent?.trim();
  if (actual !== title) {
    throw new Error(`Expected first todo title "${title}", got "${actual}"`);
  }
});

Then('the first todo is not completed', function () {
  const items = todos(this.document);
  if (items.length === 0) throw new Error('No todos in list');
  if (items[0].classList.contains('completed')) {
    throw new Error('First todo is completed but should not be');
  }
});

Then('the new-todo input is empty', function () {
  const input = el(this.document, '.new-todo');
  if (input.value !== '') {
    throw new Error(`Expected new-todo input empty, got "${input.value}"`);
  }
});

Then('the new-todo input has focus', function () {
  const input = el(this.document, '.new-todo');
  if (this.document.activeElement !== input) {
    throw new Error('new-todo input does not have focus');
  }
});

// 'all todos are completed' is defined above as Given (idempotent).

Then('all todos are not completed', function () {
  const items = todos(this.document);
  for (const li of items) {
    if (li.classList.contains('completed')) {
      throw new Error(`Todo "${el(li, '.view label')?.textContent}" is completed but should not be`);
    }
  }
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = el(this.document, '#toggle-all');
  if (!toggleAll.checked) {
    throw new Error('toggle-all checkbox is not checked');
  }
});

Then('the toggle-all checkbox is not checked', function () {
  const toggleAll = el(this.document, '#toggle-all');
  if (toggleAll.checked) {
    throw new Error('toggle-all checkbox is checked but should not be');
  }
});

// 'the todo {string} is completed' is defined above as Given (idempotent).

Then('the todo {string} is not completed', function (title) {
  const li = todoByTitle(this.document, title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  if (li.classList.contains('completed')) {
    throw new Error(`Todo "${title}" is completed but should not be`);
  }
});

// 'the todo {string} is in editing mode' is defined above as Given (idempotent).

Then('the todo {string} is not in editing mode', function (title) {
  const li = todoByTitle(this.document, title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  if (li.classList.contains('editing')) {
    throw new Error(`Todo "${title}" is in editing mode but should not be`);
  }
});

Then('the todo {string} has a destroy button', function (title) {
  const li = todoByTitle(this.document, title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  const btn = el(li, '.destroy');
  if (!btn) {
    throw new Error(`Todo "${title}" has no destroy button`);
  }
});

Then('the edit input of {string} contains {string}', function (title, value) {
  const li = todoByTitle(this.document, title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  const input = el(li, '.edit');
  if (input.value !== value) {
    throw new Error(`Edit input of "${title}" contains "${input.value}", expected "${value}"`);
  }
});

Then('the counter shows {string}', function (text) {
  const counter = el(this.document, '.todo-count');
  if (counter?.textContent?.trim() !== text) {
    throw new Error(`Counter shows "${counter?.textContent?.trim()}", expected "${text}"`);
  }
});

Then('the counter number is wrapped in a strong tag', function () {
  const strong = el(this.document, '.todo-count strong');
  if (!strong) {
    throw new Error('Counter number is not wrapped in a strong tag');
  }
  const num = parseInt(strong.textContent, 10);
  if (isNaN(num)) {
    throw new Error(`Strong tag contains "${strong.textContent}", expected a number`);
  }
});

Then('the main section is hidden', function () {
  const main = el(this.document, '.main');
  if (main.style.display !== 'none' && !main.classList.contains('hidden')) {
    // Check computed visibility: either display:none or no todos present
    const items = todos(this.document);
    if (items.length > 0) {
      throw new Error('Main section is visible but should be hidden');
    }
  }
});

Then('the main section is visible', function () {
  const main = el(this.document, '.main');
  if (main.style.display === 'none' || main.classList.contains('hidden')) {
    throw new Error('Main section is hidden but should be visible');
  }
});

Then('the footer is hidden', function () {
  const footer = el(this.document, '.footer');
  if (footer.style.display !== 'none' && !footer.classList.contains('hidden')) {
    const items = todos(this.document);
    if (items.length > 0) {
      throw new Error('Footer is visible but should be hidden');
    }
  }
});

Then('the footer is visible', function () {
  const footer = el(this.document, '.footer');
  if (footer.style.display === 'none' || footer.classList.contains('hidden')) {
    throw new Error('Footer is hidden but should be visible');
  }
});

Then('the clear-completed button is hidden', function () {
  const btn = el(this.document, '.clear-completed');
  if (btn.style.display !== 'none' && !btn.classList.contains('hidden')) {
    const completed = todos(this.document).filter((li) =>
      li.classList.contains('completed'),
    );
    if (completed.length > 0) {
      throw new Error('Clear-completed button is visible but should be hidden');
    }
  }
});

Then('the clear-completed button is visible', function () {
  const btn = el(this.document, '.clear-completed');
  if (btn.style.display === 'none' || btn.classList.contains('hidden')) {
    throw new Error('Clear-completed button is hidden but should be visible');
  }
});

Then('the todo {string} is visible', function (title) {
  const li = todoByTitle(this.document, title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  if (li.style.display === 'none' || li.classList.contains('hidden')) {
    throw new Error(`Todo "${title}" is hidden but should be visible`);
  }
});

Then('the todo {string} is hidden', function (title) {
  const li = todoByTitle(this.document, title);
  // Not in DOM = hidden (filtered out)
  if (!li) return;
  if (li.style.display !== 'none' && !li.classList.contains('hidden')) {
    throw new Error(`Todo "${title}" is visible but should be hidden`);
  }
});

Then('localStorage contains a key {string}', function (key) {
  if (this.localStorage.getItem(key) === null) {
    throw new Error(`localStorage does not contain key "${key}"`);
  }
});

Then('the {string} filter link is selected', function (linkText) {
  const links = Array.from(this.document.querySelectorAll('.filters a'));
  const link = links.find((a) => a.textContent.trim() === linkText);
  if (!link) throw new Error(`Filter link "${linkText}" not found`);
  if (!link.classList.contains('selected')) {
    throw new Error(`Filter link "${linkText}" is not selected`);
  }
});

Then('the {string} filter link is not selected', function (linkText) {
  const links = Array.from(this.document.querySelectorAll('.filters a'));
  const link = links.find((a) => a.textContent.trim() === linkText);
  if (!link) throw new Error(`Filter link "${linkText}" not found`);
  if (link.classList.contains('selected')) {
    throw new Error(`Filter link "${linkText}" is selected but should not be`);
  }
});

// ---------------------------------------------------------------------------
// DOM stability steps (for dom-stability.feature)
// ---------------------------------------------------------------------------

When('I remember the DOM node of the todo {string}', function (title) {
  const li = todoByTitle(this.document, title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  this._rememberedNode = li;
  this._rememberedNodeId = li.getAttribute('data-id');
});

Then('the remembered DOM node is still in the document', function () {
  if (!this._rememberedNode) throw new Error('No DOM node was remembered');
  const node = this._rememberedNode;
  // Check that the same object is still a child of the document
  if (!this.document.contains(node)) {
    throw new Error(
      'The remembered DOM node (data-id=' + this._rememberedNodeId + ') is no longer in the document. '
      + 'The app replaced DOM nodes instead of mutating them in place.'
    );
  }
});

Then('the remembered DOM node has the {string} class', function (className) {
  if (!this._rememberedNode) throw new Error('No DOM node was remembered');
  if (!this._rememberedNode.classList.contains(className)) {
    throw new Error(
      'The remembered DOM node (data-id=' + this._rememberedNodeId + ') does not have the "' + className + '" class. '
      + 'It has: ' + Array.from(this._rememberedNode.classList).join(', ')
    );
  }
});

Then('the remembered DOM node does not have the {string} class', function (className) {
  if (!this._rememberedNode) throw new Error('No DOM node was remembered');
  if (this._rememberedNode.classList.contains(className)) {
    throw new Error(
      'The remembered DOM node (data-id=' + this._rememberedNodeId + ') still has the "' + className + '" class '
      + 'but it should not'
    );
  }
});

Then('the toggle checkbox of the todo {string} is not visible', function (title) {
  const li = todoByTitle(this.document, title);
